mapper.select:
select a.id product_id, 2 product_type, a.project_id 'project.id', c.name 'project.name', c.short_name 'project.short_name', c.serial_number 'project.serial_number', a.monomer_id 'monomer.id', m.name 'monomer.name', a.area_id 'area.id', ar.name 'area.name', a.name, a.serial_number, a.specification, a.material, a.quantity - ifnull(sum(d.quantity), 0) as quantity, a.length, (a.quantity - ifnull(sum(d.quantity), 0)) * a.length / 1000 as total_length, a.net_weight, (a.quantity - ifnull(sum(d.quantity), 0)) * a.net_weight as total_net_weight, a.gross_weight, (a.quantity - ifnull(sum(d.quantity), 0)) * a.gross_weight as total_gross_weight, a.drawing_weight, (a.quantity - ifnull(sum(d.quantity), 0)) * a.drawing_weight as drawing_total_weight, a.surface_area / 1000000, (a.quantity - ifnull(sum(d.quantity), 0)) * a.surface_area / 1000000 as total_area from tech_artifact as a left join business_price_detail as d on a.id = d.product_id and d.bool_delete_enum = 0 and d.product_type = 2 and d.branch_company_id = #{branchCompanyId} and d.audit_status in (1, 2) left join contract_project as c on a.project_id = c.id left join plan_monomer as m on a.monomer_id = m.id left join plan_area as ar on a.area_id = ar.id where a.bool_delete_enum = 0
and a.project_id = #{projectId}
and a.monomer_id = #{monomerId}
and a.area_id = #{areaId}
and a.name like concat('%', #{name},'%')
and a.serial_number like concat('%', #{serialNumber},'%')
and a.specification like concat('%', #{specification},'%')
and a.material like concat('%', #{material},'%')
group by a.id having quantity > 0 order by a.id

select a.id as product_id, 8 product_type, a.project_id 'project.id', c.name 'project.name', c.short_name 'project.short_name', c.serial_number 'project.serial_number', a.monomer_id 'monomer.id', m.name 'monomer.name', a.area_id 'area.id', ar.name 'area.name', a.name, a.serial_number, a.specification, a.use_property, a.quantity - ifnull(sum(d.quantity), 0) as quantity, a.measure_unit, a.mete * (a.quantity - ifnull(sum(d.quantity), 0)) / a.quantity as mete, a.accounting_unit from tech_standard_part as a left join business_price_detail as d on a.id = d.product_id and d.bool_delete_enum = 0 and d.product_type = 8 and d.branch_company_id = #{branchCompanyId} and d.audit_status in (1, 2) left join contract_project as c on a.project_id = c.id left join plan_monomer as m on a.monomer_id = m.id left join plan_area as ar on a.area_id = ar.id where a.bool_delete_enum = 0
and a.project_id = #{projectId}
and a.monomer_id = #{monomerId}
and a.area_id = #{areaId}
and a.name like concat('%', #{name},'%')
and a.serial_number like concat('%', #{serialNumber},'%')
and a.specification like concat('%', #{specification},'%')
and a.use_property = 1
group by a.id having quantity > 0 order by a.id
